package top.monitorglobal.tv;
import android.content.*;import android.os.*;import java.net.*;import java.io.*;import java.util.concurrent.*;import java.util.function.BooleanSupplier;import org.json.*;
/** Independent optional I/O. Uses existing minute tick, never the seismic polling thread. */
final class RainMonitor {
 private final java.util.concurrent.Callable<JSONObject> reader;private final Context context;private final BooleanSupplier allowed;private final Handler main=new Handler(Looper.getMainLooper());private final RainOverlay overlay;private ExecutorService worker;private boolean busy,closed;private volatile HttpURLConnection connection;private int lastMode=-1;private JSONObject data;private long nextRead,demoUntil;private final Runnable demoEnd=()->{demoUntil=0;};
 RainMonitor(Context c,BooleanSupplier free){this(c,free,null);}
 RainMonitor(Context c,BooleanSupplier free,java.util.concurrent.Callable<JSONObject> read){context=c;allowed=free;if(!Prefs.get(c).getString("rainArea","").equals("liberdade-v1"))Prefs.get(c).edit().putString("rainArea","liberdade-v1").remove("rainLastKey").remove("rainLastNotice").remove("rainLastValidAt").putString("rainStatus","Liberdade: aguardando consulta").apply();reader=read==null?this::read:read;lastMode=Prefs.get(c).getInt("rainMode",2);overlay=new RainOverlay(c);}
 private int mode(){return Prefs.get(context).getInt("rainMode",2);}
 private boolean screen(){PowerManager p=context.getSystemService(PowerManager.class);return p==null||p.isInteractive();}
 void tick(){if(closed)return;int selected=mode();if(selected!=lastMode){hide();lastMode=selected;}if(selected==0||!screen()){hide();return;}if(SystemClock.elapsedRealtime()<demoUntil)return;long now=System.currentTimeMillis();RainForecast.Summary summary=null;try{if(data!=null)summary=RainForecast.summarize(data,now);}catch(JSONException ignored){}
  if(summary==null){hide();Prefs.get(context).edit().putString("rainStatus","Liberdade: estimativa por minuto indisponível ou vencida").apply();}
  else{Prefs.get(context).edit().putString("rainStatus","Liberdade: "+summary.title).apply();String previous=RainNoticePolicy.previousAfterGap(Prefs.get(context).getString("rainLastKey",""),Prefs.get(context).getLong("rainLastValidAt",0),now);Prefs.get(context).edit().putLong("rainLastValidAt",now).apply();long last=Prefs.get(context).getLong("rainLastNotice",0);if(allowed.getAsBoolean()&&RainNoticePolicy.shouldShow(summary,previous,last,now)&&overlay.show(summary,mode()==2,false))Prefs.get(context).edit().putString("rainLastKey",summary.key()).putLong("rainLastNotice",now).apply();}
  if(busy||SystemClock.elapsedRealtime()<nextRead)return;busy=true;nextRead=SystemClock.elapsedRealtime()+600000;
  if(worker==null)worker=Executors.newSingleThreadExecutor();worker.execute(()->{JSONObject result=null;try{result=reader.call();}catch(Exception ignored){}JSONObject value=result;main.post(()->{busy=false;if(closed)return;data=value;long remaining=value!=null&&value.optBoolean("ok")?value.optLong("expiresAt",0)-System.currentTimeMillis():300000;nextRead=SystemClock.elapsedRealtime()+Math.max(60000,Math.min(600000,remaining));tick();});});
 }
 private JSONObject read()throws Exception{
  HttpURLConnection c=(HttpURLConnection)new URL("https://black-sky-9ba0.terrestre.workers.dev/tv-rain?area=liberdade").openConnection();connection=c;c.setConnectTimeout(8000);c.setReadTimeout(18000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Accept","application/json");c.setRequestProperty("User-Agent","MonitorGlobalTV/"+BuildConfig.VERSION_NAME);
  try{if(c.getResponseCode()!=200)throw new IOException("Unavailable");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(bytes.size()+n>100000)throw new IOException("Response too large");bytes.write(b,0,n);}}return new JSONObject(bytes.toString("UTF-8"));}finally{c.disconnect();if(connection==c)connection=null;}
 }
 void demo(){try{long now=System.currentTimeMillis();JSONObject d=new JSONObject().put("version","tv-rain-v1").put("area","liberdade").put("ok",true).put("at",now).put("expiresAt",now+600000).put("loc",new JSONObject().put("lat",RainForecast.LATITUDE).put("lng",RainForecast.LONGITUDE));JSONArray points=new JSONArray();long start=now/60000*60000;for(int i=0;i<90;i++)points.put(new JSONObject().put("start",start+i*60000).put("end",start+(i+1)*60000).put("rate",i<30?8:0).put("type",i<30?"rain":"no_precipitation"));d.put("forecast",points);RainForecast.Summary s=RainForecast.summarize(d,now);if(s!=null){hide();demoUntil=SystemClock.elapsedRealtime()+RainOverlay.DURATION+700;overlay.show(s,true,true);main.postDelayed(demoEnd,RainOverlay.DURATION+700);}}catch(JSONException ignored){}}
 void hide(){demoUntil=0;main.removeCallbacks(demoEnd);overlay.hide();}
 void close(){closed=true;hide();main.removeCallbacksAndMessages(null);if(connection!=null)connection.disconnect();if(worker!=null)worker.shutdownNow();data=null;}
}
